package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Opens the selected claims in list order (people in the order they were added, each person's
 * claims newest first), numbering each as it is opened. A claim that cannot be opened (not a
 * draft, dated inside a closed period, not on the sheet) is refused and left as it is. Each claim
 * opened is logged and audited as a single open is: its CLAIM_OPENED line, then the figures it moved.
 */
public class OpenSelectedClaims {
    public void open(@Val Sheet sheet, @Val BulkOpenRequest request, ClaimRepository claims,
            PersonRepository people, PeriodRepository periods, SheetRepository sheets, RateRepository rates,
            SettingsRepository settings, ClaimLogRepository log, HttpServletRequest http, Audit audit,
            Out<BulkOpenResponse> result) {
        String user = Audit.user(http);
        Set<Long> selected = new HashSet<>();
        for (String id : request.claimIds()) {
            try {
                selected.add(Long.parseLong(id.trim()));
            } catch (NumberFormatException | NullPointerException e) {
                // not an id: no claim on the sheet, so refused below
            }
        }
        int requested = new HashSet<>(request.claimIds()).size();
        int opened = 0;
        Rollup before = rollup(sheet, sheets, people, claims, rates, settings);
        for (Person person : people.findAll(sheet.id())) {
            List<Claim> theirs = claims.findByPerson(sheet.id(), person.getId());
            for (Claim claim : theirs) {
                if (!selected.contains(claim.getId())) continue;
                if (!opens(sheet, claim, periods, claims)) continue;
                claim.setOpenedBy(user);
                claim.setNumber(ClaimNumbers.next(sheet, claim, settings.find(sheet.id()), periods, claims));
                claims.save(claim);
                log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
                opened++;
                audit.record(ClaimAudit.line(claim.getStatus().auditEvent(), sheet, user, person, claim));
                Rollup after = rollup(sheet, sheets, people, claims, rates, settings);
                after.changesSince(before, sheet.id(), user).forEach(audit::record);
                before = after;
            }
        }
        result.set(new BulkOpenResponse(opened, requested - opened));
    }

    /** Moves the claim to OPEN when its status and period allow it and no one opened it first. */
    private static boolean opens(Sheet sheet, Claim claim, PeriodRepository periods, ClaimRepository claims) {
        if (periods.closedOn(sheet.id(), claim.getDate()) != null) return false;
        try {
            claim.moveTo(ClaimStatus.OPEN);
        } catch (InvalidClaimStatusException e) {
            return false;
        }
        return claims.markOpened(claim);
    }

    private static Rollup rollup(Sheet sheet, SheetRepository sheets, PersonRepository people, ClaimRepository claims,
            RateRepository rates, SettingsRepository settings) {
        return Rollup.of(sheet.id(), sheets.today(sheet.id()), people, claims, rates, settings.find(sheet.id()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithBulkOpen {
    public void respond(@Val BulkOpenResponse result, ObjectResponse<BulkOpenResponse> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Settles the claim and fixes its due: its amount times the rate of its person's grade in force on its date, in force on the
 * claim's date, divided by 100 and rounded to two decimals as the claim rounds (by the sheet's policy date), at least the sheet's floor. With no such rate the due is
 * not fixed. A claim a statement bound is settled at its bound figure. The late charge it has gained
 * by the sheet's today is frozen in on top. The user who opened the claim may not settle it.
 * When a clerk (any user not made a steward) settles a claim whose due is above the sheet's clerk
 * limit, it goes to PENDING instead, its due left live until a steward approves or rejects it; a
 * due of n/a is within any limit.
 */
public class SettleClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
            RoleRepository roles, SettingsRepository settingsStore, HttpServletRequest request)
            throws InvalidClaimStatusException, SelfSettleException {
        Person person = people.find(sheet.id(), claim.getPersonId());
        Settings settings = settingsStore.find(sheet.id());
        BigDecimal figure = claim.isStated() ? claim.getStatedDue()
                : ClaimFigure.live(claim, rates.findAll(sheet.id()), person.gradeOn(claim.getDate()), settings,
                        sheet.today());
        // The late charge is read while the claim is still OPEN.
        BigDecimal late = ClaimFigure.late(claim, figure, settings, sheet.today());
        if (!claim.getStatus().canMoveTo(ClaimStatus.SETTLED)) {
            throw new InvalidClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
        }
        String user = Audit.user(request);
        if (user.equals(claim.getOpenedBy())) throw new SelfSettleException(user);
        BigDecimal due = figure == null ? null : figure.add(late);
        if (!settings.withinClerkLimit(due) && Role.CLERK.equals(roles.roleOf(sheet.id(), user))) {
            claim.moveTo(ClaimStatus.PENDING);
            return;
        }
        claim.moveTo(ClaimStatus.SETTLED);
        claim.setSettledDue(due);
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Opens the claim, recording the signed-in user who opened it. */
public class OpenClaim {
    public void apply(@Val Claim claim, HttpServletRequest request) throws InvalidClaimStatusException {
        claim.moveTo(ClaimStatus.OPEN);
        claim.setOpenedBy(Audit.user(request));
    }
}

